layer.css:
article[data-ryt="rec-card"] { border-bottom: 1px solid rgb(31, 32, 35); border-radius: 0px; transition: all; border-top: none; border-right: none; border-left: none }
[data-ryt="brand"] { color: rgb(226, 88, 34); border-radius: 0px; font-family: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, "Courier New", monospace; font-size: 14px; font-weight: 400; font-style: normal; line-height: 1.65; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(226, 88, 34); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.15s cubic-bezier(0.25, 0.46, 0.45, 0.94) }
[data-ryt="nav"] a { color: var(--ryt-accent); border-radius: 0px; font-family: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, "Courier New", monospace; font-size: 14px; font-weight: 400; font-style: normal; line-height: 1.65; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 4px; padding-right: 0px; padding-bottom: 4px; padding-left: 0px; transition: color 0.15s cubic-bezier(0.25, 0.46, 0.45, 0.94) }
[data-ryt="button"] { color: rgb(164, 164, 164); background-color: rgb(22, 23, 25); border-top: 1px solid rgb(42, 43, 46); border-right: 1px solid rgb(42, 43, 46); border-bottom: 1px solid rgb(42, 43, 46); border-left: 1px solid rgb(42, 43, 46); border-radius: 4px; font-family: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, "Courier New", monospace; font-weight: 400; font-style: normal; line-height: 1.65; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(164, 164, 164); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 7.2px; padding-right: 13.6px; padding-bottom: 7.2px; padding-left: 13.6px; transition: color 0.15s cubic-bezier(0.25, 0.46, 0.45, 0.94), border-color 0.15s cubic-bezier(0.25, 0.46, 0.45, 0.94), background 0.15s cubic-bezier(0.25, 0.46, 0.45, 0.94) }
[data-ryt="category"], [data-ryt="tags"] li { color: rgb(164, 164, 164); background-color: rgb(22, 23, 25); border-top: 1px solid rgb(42, 43, 46); border-right: 1px solid rgb(42, 43, 46); border-bottom: 1px solid rgb(42, 43, 46); border-left: 1px solid rgb(42, 43, 46); border-radius: 999px; font-family: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, "Courier New", monospace; font-weight: 400; font-style: normal; line-height: 1.65; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(164, 164, 164); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 2.88px; padding-right: 8.8px; padding-bottom: 2.88px; padding-left: 8.8px; transition: color 0.15s cubic-bezier(0.25, 0.46, 0.45, 0.94), border-color 0.15s cubic-bezier(0.25, 0.46, 0.45, 0.94) }
[data-ryt="review"] { color: rgb(164, 164, 164); font-family: var(--ryt-font-heading); font-size: 14.72px; font-weight: 400; font-style: normal; line-height: 1.65; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(164, 164, 164); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, "Courier New", monospace; font-size: 12.48px; font-weight: 400; font-style: normal; line-height: 1.65; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16.8px; font-weight: 400; font-style: normal; line-height: 1.4; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"]:hover { color: #e25822 }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: #e25822 }
[data-ryt="category"]::before, [data-ryt="tags"] li::before { content: "#"; display: block; width: 6.92188px; height: 19px; margin-right: 2.4px; color: rgb(226, 88, 34); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, "Courier New", monospace; font-size: 11.52px; font-weight: 400; font-style: normal; line-height: 1.65; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(226, 88, 34); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: rgb(226, 88, 34) }
[data-ryt="category"]:hover, [data-ryt="tags"] li:hover { color: #ececec }
[data-ryt="button"]:hover { color: #ececec }
[data-ryt="nav"] a::before { content: "›"; display: block; width: 8.40625px; height: 23.0938px; color: rgb(138, 138, 138); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, "Courier New", monospace; font-size: 14px; font-weight: 400; font-style: normal; line-height: 1.65; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(138, 138, 138); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: color 0.15s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.15s cubic-bezier(0.25, 0.46, 0.45, 0.94); -webkit-text-fill-color: rgb(138, 138, 138) }
[data-ryt="nav"] a:hover { color: #e25822 }
[data-ryt="brand"]::before { content: "›"; display: block; width: 8.40625px; height: 23.0938px; color: rgb(226, 88, 34); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, "Courier New", monospace; font-size: 14px; font-weight: 400; font-style: normal; line-height: 1.65; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(226, 88, 34); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: color 0.15s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.15s cubic-bezier(0.25, 0.46, 0.45, 0.94); -webkit-text-fill-color: rgb(226, 88, 34) }
[data-ryt="brand"]:hover { color: #e25822 }
article[data-ryt="rec-card"]:hover { background-image: initial; background-color: rgba(226, 88, 34, 0.03) }
